package org.acme.model;

import com.fasterxml.jackson.annotation.JsonIgnore;
import jakarta.persistence.*;
import org.hibernate.annotations.UuidGenerator;
import java.time.LocalDateTime;
import java.time.Instant;
import java.util.UUID;

/** Employee profile projection persisted in the talent schema. */
@Entity
@Table(name = "tb_employee", schema = "talent")
public class Employee {

    /** Creates an empty employee entity. */
    public Employee() {
    }

    /** Employee identifier generated by Hibernate. */
    @Id
    @UuidGenerator(style = UuidGenerator.Style.TIME) // Gera o UUIDv7 automaticamente
    @Column(name = "id", updatable = false, nullable = false)
    public UUID id;

    /** Employee's display name. */
    @Column(nullable = false, length = 150)
    public String name;

    /** Unique employee email address. */
    @Column(nullable = false, unique = true, length = 150)
    public String email;

    /** Employee's role. */
    @Column(nullable = false, length = 100)
    public String role;

    /** Employee's seniority level. */
    @Column(nullable = false, length = 50)
    public String seniority;

    /** Local date and time when the entity was initialized. */
    @Column(name = "created_at", updatable = false)
    public LocalDateTime createdAt = LocalDateTime.now();

    /** Local date and time when the profile was last updated. */
    @Column(name = "updated_at")
    public LocalDateTime updatedAt = LocalDateTime.now();

    /** Current version of this employee's event stream; excluded from JSON. */
    @Column(name = "version", nullable = false)
    @JsonIgnore
    public long version;

    /** Deletion timestamp for a soft-deleted employee; excluded from JSON. */
    @Column(name = "deleted_at")
    @JsonIgnore
    public Instant deletedAt;
}
